/**
 * Reporting utility for Naive Matching Pipeline E2E Verification.
 *
 * Queries Trip Service for all rides generated by the simulated riders,
 * computes aggregation metrics (total rides, state distribution, average time-to-match),
 * and asserts against the configured MIN_MATCH_SUCCESS_RATE.
 */

const jwt = require('jsonwebtoken');

async function main() {
  const invokeUrl = (process.env.INVOKE_URL || '').replace(/\/+$/, '');
  const jwtSecret = process.env.JWT_SECRET || 'dev-jwt-secret-for-ride-dispatch-local-testing';
  const riderCount = parseInt(process.env.RIDER_COUNT || '5', 10);
  const driverCount = parseInt(process.env.DRIVER_COUNT || '10', 10);
  const runDurationSeconds = parseInt(process.env.RUN_DURATION_SECONDS || '150', 10);
  const riderIdPrefix = process.env.RIDER_ID_PREFIX || '';
  const minMatchSuccessRate = parseFloat(process.env.MIN_MATCH_SUCCESS_RATE || '0.5');

  if (!invokeUrl) {
    console.error('ERROR: INVOKE_URL is required for E2E reporter');
    process.exit(1);
  }

  console.log(`\nGathering ride history across ${riderCount} simulated riders...`);

  const allRides = [];

  for (let i = 1; i <= riderCount; i++) {
    const riderId = riderIdPrefix ? `${riderIdPrefix}-rider-${i}` : `sim-rider-${i}`;
    const token = jwt.sign(
      { sub: riderId, role: 'rider' },
      jwtSecret,
      { algorithm: 'HS256', expiresIn: '1h' }
    );

    const url = `${invokeUrl}/riders/${riderId}/rides`;
    try {
      const res = await fetch(url, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      if (!res.ok) {
        console.warn(`[WARN] Failed to fetch rides for ${riderId}: HTTP ${res.status}`);
        continue;
      }

      const rides = await res.json();
      if (Array.isArray(rides)) {
        allRides.push(...rides);
      }
    } catch (err) {
      console.warn(`[WARN] Network error fetching rides for ${riderId}:`, err.message);
    }
  }

  // Metrics computation
  const totalRides = allRides.length;
  let matchedCount = 0;
  let driverEnRouteCount = 0;
  let inProgressCount = 0;
  let completedCount = 0;
  let requestedCount = 0;
  let cancelledCount = 0;
  let otherCount = 0;

  const matchDurationsSec = [];

  for (const ride of allRides) {
    switch (ride.state) {
      case 'MATCHED':
        matchedCount++;
        break;
      case 'DRIVER_EN_ROUTE':
        driverEnRouteCount++;
        break;
      case 'IN_PROGRESS':
        inProgressCount++;
        break;
      case 'COMPLETED':
        completedCount++;
        break;
      case 'REQUESTED':
        requestedCount++;
        break;
      case 'CANCELLED':
        cancelledCount++;
        break;
      default:
        otherCount++;
        break;
    }

    const isMatchedOrFurther = ['MATCHED', 'DRIVER_EN_ROUTE', 'IN_PROGRESS', 'COMPLETED'].includes(ride.state);
    if (isMatchedOrFurther && ride.createdAt && ride.updatedAt) {
      const created = new Date(ride.createdAt).getTime();
      const updated = new Date(ride.updatedAt).getTime();
      if (!isNaN(created) && !isNaN(updated) && updated >= created) {
        matchDurationsSec.push((updated - created) / 1000);
      }
    }
  }

  const matchedOrFurther = matchedCount + driverEnRouteCount + inProgressCount + completedCount;
  const matchSuccessRate = totalRides > 0 ? (matchedOrFurther / totalRides) : 0;

  const avgTimeToMatchSec =
    matchDurationsSec.length > 0
      ? matchDurationsSec.reduce((a, b) => a + b, 0) / matchDurationsSec.length
      : 0;

  // Format percentages and durations
  const actualPercent = (matchSuccessRate * 100).toFixed(1);
  const targetPercent = (minMatchSuccessRate * 100).toFixed(1);
  const avgTimeStr = avgTimeToMatchSec > 0 ? `${avgTimeToMatchSec.toFixed(2)}s` : 'N/A';

  // Demo mode formatted summary report
  console.log('\n==================================================================');
  console.log('             END-TO-END NAIVE MATCHING PIPELINE REPORT');
  console.log('==================================================================');
  console.log(`Simulated Drivers:       ${driverCount} (ID Prefix: "${riderIdPrefix || 'sim'}")`);
  console.log(`Simulated Riders:        ${riderCount} (ID Prefix: "${riderIdPrefix || 'sim'}")`);
  console.log(`Simulation Duration:     ${runDurationSeconds} seconds`);
  console.log(`Required Match Rate:     ${targetPercent}% (MIN_MATCH_SUCCESS_RATE: ${minMatchSuccessRate})`);
  console.log('------------------------------------------------------------------');
  console.log(`Total Rides Generated:   ${totalRides}`);
  console.log(`Matched or Further:      ${matchedOrFurther} (MATCHED: ${matchedCount}, EN_ROUTE: ${driverEnRouteCount}, IN_PROGRESS: ${inProgressCount}, COMPLETED: ${completedCount})`);
  console.log(`Still Pending/REQUESTED: ${requestedCount}`);
  console.log(`Cancelled / Other:       ${cancelledCount + otherCount}`);
  console.log('------------------------------------------------------------------');
  console.log(`Actual Match Rate:       ${actualPercent}%`);
  console.log(`Average Time-to-Match:   ${avgTimeStr} (approximate, based on createdAt -> updatedAt)`);
  console.log('==================================================================');

  if (totalRides === 0) {
    console.error(`\n[FAIL] Zero rides were created during the simulation window (${runDurationSeconds}s).`);
    process.exit(1);
  }

  if (matchSuccessRate >= minMatchSuccessRate) {
    console.log(`\n[PASS] Match success rate (${actualPercent}%) meets/exceeds target (${targetPercent}%).`);
    process.exit(0);
  } else {
    console.error(`\n[FAIL] Match success rate (${actualPercent}%) fell below target (${targetPercent}%).`);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error('Fatal error generating report:', err);
  process.exit(1);
});
